class Slide{
 constructor(title,section='OUR RESEARCH',sub=''){this.n=slides.length+1;this.title=title;this.s=[];this.id=2;this.rels=[];this.notes='';slides.push(this);this.text(.6,.5,12.1,.7,title,{size:32,bold:true,color:C.navy});if(sub)this.text(.62,1.35,12.0,.6,sub,{size:17,color:C.muted});this.line(.55,7.1,12.22,7.1,C.line,.6);this.text(.57,7.22,10.7,.19,'Selective evidence propagation · Preliminary research · 1 November 2026',{size:9,color:C.muted});this.text(12.15,7.2,.6,.25,String(this.n).padStart(2,'0'),{size:10,color:C.muted,align:'r'});}
 record(type,x,y,w,h,text=''){allGeometry.push({slide:this.n,type,x,y,w,h,text:String(text).slice(0,90)});}
 text(x,y,w,h,text,opt={}){this.record('text',x,y,w,h,text);const i=this.id++;this.s.push(`<p:sp><p:nvSpPr><p:cNvPr id="${i}" name="Text ${i}"/><p:cNvSpPr txBox="1"/><p:nvPr/></p:nvSpPr><p:spPr><a:xfrm><a:off x="${em(x)}" y="${em(y)}"/><a:ext cx="${em(w)}" cy="${em(h)}"/></a:xfrm><a:prstGeom prst="rect"><a:avLst/></a:prstGeom><a:noFill/><a:ln><a:noFill/></a:ln></p:spPr><p:txBody>${txBody(text,opt)}</p:txBody></p:sp>`);return i;}
 box(x,y,w,h,text,opt={}){this.record('shape',x,y,w,h,text);let i=this.id++;this.s.push(`<p:sp><p:nvSpPr><p:cNvPr id="${i}" name="${xml(opt.name??'Diagram node')} ${i}"/><p:cNvSpPr/><p:nvPr/></p:nvSpPr><p:spPr><a:xfrm><a:off x="${em(x)}" y="${em(y)}"/><a:ext cx="${em(w)}" cy="${em(h)}"/></a:xfrm><a:prstGeom prst="${opt.geom??'rect'}"><a:avLst/></a:prstGeom>${opt.fill?`<a:solidFill><a:srgbClr val="${opt.fill}"/></a:solidFill>`:'<a:noFill/>'}<a:ln w="${Math.round((opt.width??1)*12700)}"><a:solidFill><a:srgbClr val="${opt.stroke??C.line}"/></a:solidFill></a:ln></p:spPr>${text?`<p:txBody>${txBody(text,{pad:.12,anchor:'ctr',align:'ctr',size:opt.size??20,...opt})}</p:txBody>`:''}</p:sp>`);return i;}
 line(x1,y1,x2,y2,color=C.line,width=1,arrow=false){this.record('connector',Math.min(x1,x2),Math.min(y1,y2),Math.abs(x2-x1),Math.abs(y2-y1));let i=this.id++;this.s.push(`<p:cxnSp><p:nvCxnSpPr><p:cNvPr id="${i}" name="Connector ${i}"/><p:cNvCxnSpPr/><p:nvPr/></p:nvCxnSpPr><p:spPr><a:xfrm${x2<x1?' flipH="1"':''}${y2<y1?' flipV="1"':''}><a:off x="${em(Math.min(x1,x2))}" y="${em(Math.min(y1,y2))}"/><a:ext cx="${em(Math.abs(x2-x1))}" cy="${em(Math.abs(y2-y1))}"/></a:xfrm><a:prstGeom prst="line"><a:avLst/></a:prstGeom><a:ln w="${Math.round(width*12700)}"><a:solidFill><a:srgbClr val="${color}"/></a:solidFill>${arrow?'<a:tailEnd type="triangle" w="sm" len="sm"/>':''}</a:ln></p:spPr><p:style><a:lnRef idx="0"><a:schemeClr val="accent1"/></a:lnRef><a:fillRef idx="0"><a:schemeClr val="accent1"/></a:fillRef><a:effectRef idx="0"><a:schemeClr val="accent1"/></a:effectRef><a:fontRef idx="minor"><a:schemeClr val="lt1"/></a:fontRef></p:style></p:cxnSp>`);}
 note(content,sources=[]){this.notes=content+'\n\nSOURCES\n'+sources.map(s=>'- '+s).join('\n');}
 table(x,y,width,headers,rows,opt={}){const widths=opt.widths??headers.map((_,i)=>i===0?width*.28:width*.72/(headers.length-1));const rh=opt.rowHeight??.52,hh=opt.headerHeight??.6;let i=this.id++;this.record('native_table',x,y,width,hh+rh*rows.length);
 let cells=(vals,ri)=>vals.map((v,ci)=>{v=typeof v==='object'?v:{text:String(v)};let bottom=(ri===0||ri===rows.length)?C.ink:null;const stroke=(which)=>`<a:ln${which} w="${ri===rows.length?16000:9500}">${(which==='T'&&ri===0)|| (which==='B'&&bottom)?`<a:solidFill><a:srgbClr val="${C.ink}"/></a:solidFill>`:'<a:noFill/>'}</a:ln${which}>`;return `<a:tc><a:txBody>${txBody(v.text,{size:v.size??opt.size??18,font:opt.font??'Times New Roman',bold:v.bold??ri===0,color:v.color??(ri===rows.length&&opt.oursLast?C.teal:C.ink),align:ci===0?'l':'ctr',anchor:'ctr',line:1.02,pad:.07,after:0})}</a:txBody><a:tcPr marL="${em(.07)}" marR="${em(.07)}" marT="${em(.04)}" marB="${em(.04)}">${stroke('L')}${stroke('R')}${stroke('T')}${stroke('B')}${ri===rows.length&&opt.oursLast?`<a:solidFill><a:srgbClr val="F0F7F6"/></a:solidFill>`:'<a:noFill/>'}</a:tcPr></a:tc>`;}).join('');
 this.s.push(`<p:graphicFrame><p:nvGraphicFramePr><p:cNvPr id="${i}" name="Editable table ${i}"/><p:cNvGraphicFramePr/><p:nvPr/></p:nvGraphicFramePr><p:xfrm><a:off x="${em(x)}" y="${em(y)}"/><a:ext cx="${em(width)}" cy="${em(hh+rh*rows.length)}"/></p:xfrm><a:graphic><a:graphicData uri="http://schemas.openxmlformats.org/drawingml/2006/table"><a:tbl><a:tblPr firstRow="0" bandRow="0"><a:tableStyleId>{5C22544A-7EE6-4342-B048-85BDC9FD1C3A}</a:tableStyleId></a:tblPr><a:tblGrid>${widths.map(w=>`<a:gridCol w="${em(w)}"/>`).join('')}</a:tblGrid><a:tr h="${em(hh)}">${cells(headers,0)}</a:tr>${rows.map((r,ri)=>`<a:tr h="${em(rh)}">${cells(r,ri+1)}</a:tr>`).join('')}</a:tbl></a:graphicData></a:graphic></p:graphicFrame>`);}
 chart(x,y,w,h,categories,series,opt={}){const n=++chartCount,i=this.id++,rid='rId'+(this.rels.length+2);this.rels.push([rid,'chart',`../charts/chart${n}.xml`]);this.record('native_chart',x,y,w,h);this.s.push(`<p:graphicFrame><p:nvGraphicFramePr><p:cNvPr id="${i}" name="Editable chart ${n}"/><p:cNvGraphicFramePr/><p:nvPr/></p:nvGraphicFramePr><p:xfrm><a:off x="${em(x)}" y="${em(y)}"/><a:ext cx="${em(w)}" cy="${em(h)}"/></p:xfrm><a:graphic><a:graphicData uri="http://schemas.openxmlformats.org/drawingml/2006/chart"><c:chart xmlns:c="http://schemas.openxmlformats.org/drawingml/2006/chart" r:id="${rid}"/></a:graphicData></a:graphic></p:graphicFrame>`);makeChart(n,categories,series,opt);}
}
function makeWorkbook(n,cats,series){const d=path.join(DIR,`workbook_${n}`);fs.rmSync(d,{recursive:true,force:true});fs.mkdirSync(d,{recursive:true});const f=(p,s)=>{fs.mkdirSync(path.dirname(path.join(d,p)),{recursive:true});fs.writeFileSync(path.join(d,p),s)};
 const col=i=>String.fromCharCode(65+i);const textcell=(c,r,v)=>`<c r="${c}${r}" t="inlineStr"><is><t>${xml(v)}</t></is></c>`;
 f('[Content_Types].xml',decl+'<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/worksheets/sheet1.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/></Types>');
 f('_rels/.rels',rels([['rId1','officeDocument','xl/workbook.xml']])); f('xl/workbook.xml',decl+'<workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets><sheet name="Data" sheetId="1" r:id="rId1"/></sheets></workbook>');f('xl/_rels/workbook.xml.rels',rels([['rId1','worksheet','worksheets/sheet1.xml']]));
 f('xl/worksheets/sheet1.xml',decl+'<worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetData><row r="1">'+textcell('A',1,'Condition')+series.map((s,i)=>textcell(col(i+1),1,s.name)).join('')+'</row>'+cats.map((c,i)=>`<row r="${i+2}">${textcell('A',i+2,c)}${series.map((s,j)=>`<c r="${col(j+1)}${i+2}"><v>${s.values[i]}</v></c>`).join('')}</row>`).join('')+'</sheetData></worksheet>');
 fs.mkdirSync(path.join(PKG,'ppt/embeddings'),{recursive:true});execFileSync('/usr/bin/zip',['-q','-r',path.join(PKG,`ppt/embeddings/chart${n}.xlsx`),'.'],{cwd:d});
}
function makeChart(n,cats,series,opt){makeWorkbook(n,cats,series);const cache=(tag,vals)=>`<c:${tag}><c:ptCount val="${vals.length}"/>${vals.map((v,i)=>`<c:pt idx="${i}"><c:v>${xml(v)}</c:v></c:pt>`).join('')}</c:${tag}>`;const txpr=`<c:txPr><a:bodyPr/><a:lstStyle/><a:p><a:pPr><a:defRPr sz="1600"><a:solidFill><a:srgbClr val="${C.ink}"/></a:solidFill><a:latin typeface="Arial"/></a:defRPr></a:pPr><a:endParaRPr lang="en-US"/></a:p></c:txPr>`;
 const ser=series.map((s,i)=>`<c:ser><c:idx val="${i}"/><c:order val="${i}"/><c:tx><c:strRef><c:f>Data!$${String.fromCharCode(66+i)}$1</c:f>${cache('strCache',[s.name])}</c:strRef></c:tx><c:spPr><a:solidFill><a:srgbClr val="${s.color}"/></a:solidFill><a:ln><a:noFill/></a:ln></c:spPr><c:cat><c:strRef><c:f>Data!$A$2:$A$${cats.length+1}</c:f>${cache('strCache',cats)}</c:strRef></c:cat><c:val><c:numRef><c:f>Data!$${String.fromCharCode(66+i)}$2:$${String.fromCharCode(66+i)}$${cats.length+1}</c:f><c:numCache><c:formatCode>0</c:formatCode><c:ptCount val="${cats.length}"/>${s.values.map((v,j)=>`<c:pt idx="${j}"><c:v>${v}</c:v></c:pt>`).join('')}</c:numCache></c:numRef></c:val></c:ser>`).join('');
 write(`ppt/charts/chart${n}.xml`,decl+`<c:chartSpace xmlns:c="http://schemas.openxmlformats.org/drawingml/2006/chart" xmlns:a="http://schemas.openxmlformats.org/drawingml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><c:lang val="en-US"/><c:chart><c:autoTitleDeleted val="1"/><c:plotArea><c:layout/><c:barChart><c:barDir val="col"/><c:grouping val="clustered"/><c:varyColors val="0"/>${ser}<c:dLbls><c:showLegendKey val="0"/><c:showVal val="1"/><c:showCatName val="0"/><c:showSerName val="0"/><c:showPercent val="0"/>${txpr}</c:dLbls><c:gapWidth val="130"/><c:overlap val="0"/><c:axId val="100"/><c:axId val="200"/></c:barChart><c:catAx><c:axId val="100"/><c:scaling><c:orientation val="minMax"/></c:scaling><c:delete val="0"/><c:axPos val="b"/><c:majorTickMark val="none"/><c:minorTickMark val="none"/><c:tickLblPos val="nextTo"/>${txpr}<c:crossAx val="200"/><c:crosses val="autoZero"/><c:auto val="1"/><c:lblAlgn val="ctr"/><c:lblOffset val="100"/></c:catAx><c:valAx><c:axId val="200"/><c:scaling><c:orientation val="minMax"/><c:max val="${opt.max??20}"/><c:min val="0"/></c:scaling><c:delete val="0"/><c:axPos val="l"/><c:majorGridlines><c:spPr><a:ln w="5000"><a:solidFill><a:srgbClr val="${C.gray}"/></a:solidFill></a:ln></c:spPr></c:majorGridlines><c:numFmt formatCode="0" sourceLinked="0"/><c:majorTickMark val="none"/><c:tickLblPos val="nextTo"/>${txpr}<c:crossAx val="100"/><c:crosses val="autoZero"/><c:crossBetween val="between"/><c:majorUnit val="${opt.unit??5}"/></c:valAx></c:plotArea><c:legend><c:legendPos val="b"/><c:layout/>${txpr}<c:overlay val="0"/></c:legend><c:plotVisOnly val="1"/><c:dispBlanksAs val="gap"/></c:chart><c:spPr><a:noFill/><a:ln><a:noFill/></a:ln></c:spPr>${txpr}<c:externalData r:id="rId1"><c:autoUpdate val="0"/></c:externalData></c:chartSpace>`);write(`ppt/charts/_rels/chart${n}.xml.rels`,rels([['rId1','package',`../embeddings/chart${n}.xlsx`]]));}
