{
 const s=new Slide('What is complete and what the next study needs','','Current finding: selective propagation has not demonstrated an advantage over simpler reputation');
 label(s,.75,2.13,5.7,'Implemented and exercised',C.teal,25);label(s,7.12,2.13,5.5,'Needed for a credible next test',C.navy,25);
 para(s,.8,3.0,5.45,2.9,'Linked records and synthetic provenance\nEvidence ledger and R/C/M/S rules\nAuthority-aware retrieval integration\nReplay, restart and matched evaluation',22);
 s.line(6.62,2.2,6.62,6.1,C.line,.8);
 para(s,7.16,3.0,5.35,2.9,'Trace the changed contexts and errors\nValidate source attribution and exact uses\nAdd useful external-memory questions\nFreeze new cohorts before new outcomes',22);
 para(s,.85,6.25,11.7,.6,'Human review is still pending. Our method has not run on full MPBench.',23,C.teal);
 small(s,'Retain original authority, equal audit budgets and strong C/M comparisons. Do not scale a weakly informative setup to claim efficacy.',6.83);
 s.note('The prototype is implemented and exercised, but the claimed selective propagation benefit is not demonstrated. Before new paid scaling, inspect all changed contexts and errors to separate direct containment from transfer to unaudited siblings. Validate provenance and record/use safety with two independent people and a third adjudicator for disagreements. Current human safety labels and validated source-grounded utility questions are both zero. The actual AI review quality and false accusations require careful review; original case labels are not substitute memory truth. Prospectively define external-memory tasks with eligible supporting records under unchanged authority, validate references and benign uses, freeze a new case/template cohort and compare shared feedback against C and M at equal utility/cost. Prepared case-intent bags do not satisfy the primary protocol’s verified 16-safe/16-unsafe balance. Add recent-history C, fixed-mixture M and answer-level compromise/noise/delay/false-accusation/permission tests before a broad paper claim. A new version cannot relabel inspected development outcomes as untouched confirmation. Original full-release reproduction, our limited pilot and a future human-validated study remain distinct.',[SRC.protocol+' §§15–18',SRC.pilot,SRC.audit]);
}
